import sys
import importlib.metadata

packages = [
    "pandas", "numpy", "matplotlib", "pyyaml", "scikit-learn", "lightgbm", "pytest", "pyarrow"
]

print("Installed versions:")
for pkg in packages:
    try:
        ver = importlib.metadata.version(pkg)
        print(f"  {pkg}: {ver}")
    except Exception as e:
        print(f"  {pkg}: NOT INSTALLED ({e})")

